/* Duas portas, e o que cada uma compraria.

   telefone/e-mail  se a busca alcançar o Arquivo, dá para varrer usando os
                    CPFs e telefones que já temos e recuperar os pedidos
                    daqueles clientes — não tudo, mas o histórico de quem
                    interessa: quem já é cliente.

   diário           se ele listar eventos de pedido arquivado, temos ao menos
                    a LISTA de números e as datas. Sem cliente e sem valor,
                    mas é o esqueleto — e talvez o caminho para saber quantos
                    e quais faltam.

   A regra do veredito é a de sempre: só conta se vier O PEDIDO PEDIDO.
   Parâmetro que a BaseLinker não reconhece não dá erro, ela devolve dados
   como se o filtro tivesse funcionado. */
const d = $('Dados da sonda').first().json;
const alvo = String(d.numeroArquivado || '');
const out = { pedidoArquivado: alvo };
const resp = (no) => { try { return $(no).first().json || {}; } catch (e) { return { _naoRodou: true }; } };

function porBusca(no, rotulo, preenchido) {
  const r = resp(no);
  if (!preenchido) return 'PULADO — preencha ' + rotulo + ' em "Dados da sonda"';
  if (r.status !== 'SUCCESS') return 'RECUSOU — ' + (r.error_message || r.error_code || '');
  const lista = r.orders || [];
  return lista.some(p => String(p.order_id) === alvo)
    ? 'ALCANÇA — a busca por ' + rotulo + ' devolve pedido do Arquivo'
    : 'não alcança (' + lista.length + ' pedido(s), nenhum é o arquivado)';
}

out.porTelefone = porBusca('Base · pedidos por telefone', 'telefone', !!String(d.telefone || '').trim());
out.porEmail    = porBusca('Base · pedidos por e-mail',   'e-mail',   !!String(d.email || '').trim());

const jr = resp('Base · diário (last_log_id 1)');
if (jr.status !== 'SUCCESS') {
  out.porDiario = 'RECUSOU — ' + (jr.error_message || jr.error_code || '');
} else {
  const logs = jr.logs || [];
  const ids = [...new Set(logs.map(l => String(l.order_id || '')).filter(Boolean))];
  const temAlvo = ids.indexOf(alvo) >= 0;
  /* Id de pedido arquivado é bem menor que o dos ativos — os da tela estão
     em 37 milhões, os ativos passam de 47. Se o diário trouxer ids baixos,
     ele enxerga o Arquivo mesmo sem trazer o pedido exato. */
  const baixos = ids.filter(x => Number(x) > 0 && Number(x) < 45000000).length;
  out.porDiario = temAlvo
    ? 'ALCANÇA — o diário traz eventos do pedido arquivado'
    : (baixos
        ? 'PARCIAL — ' + baixos + ' de ' + ids.length + ' pedidos do diário têm id de faixa arquivada'
        : 'não alcança (' + ids.length + ' pedido(s) no diário, todos da faixa ativa)');
  out.diarioAmostra = ids.slice(0, 5).join(', ');
}

const abriu = /ALCANÇA/.test(out.porTelefone) || /ALCANÇA/.test(out.porEmail) || /ALCANÇA|PARCIAL/.test(out.porDiario);
out.conclusao = abriu
  ? 'Abriu — me manda esta saída que eu uso para alcançar os pedidos sem nota.'
  : 'Fechou. Para os ~10.100 sem nota fiscal, só o CSV da tela da Base.';
return [{ json: out }];
